function MAX-SIDON-INTERVAL(n):
    best <- []
    procedure EXTEND(S, D, start):        # D = differences realised by S
        if |S| > |best|: best <- S
        if |S| + (n - start) <= |best|: return        # bound-and-prune
        for x = start .. n-1:
            New <- { x - s : s in S }
            if |New| = |S| and New ∩ D = empty:       # no repeated distance
                EXTEND(S + [x], D ∪ New, x + 1)
    EXTEND([], empty, 0)
    return (|best|, best)

